<?php
// Shared-host fallback. Laravel mode uses the Eloquent controllers; this mode keeps the upload working without Composer/SSH.
$path = parse_url($_SERVER['REQUEST_URI'] ?? '/', PHP_URL_PATH) ?: '/';
$base = rtrim(str_replace('\\', '/', dirname($_SERVER['SCRIPT_NAME'] ?? '')), '/');
if ($base !== '' && $base !== '/' && str_starts_with($path, $base)) $path = substr($path, strlen($base)) ?: '/';
$path = '/' . trim($path, '/');
$store = json_decode(file_get_contents(__DIR__ . '/database/data.json'), true);
$esc = static fn($v) => htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8');
$root = static fn($p) => (($b = rtrim(dirname($_SERVER['SCRIPT_NAME'] ?? ''), '/')) === '' || $b === '/') ? $p : $b . $p;
$title = match ($path) { '/customers' => 'Customer Accounts', '/users' => 'User Accounts', '/about' => 'About This Application', default => 'Laravel POS Eloquent' };
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $esc($title) ?></title><style>:root{--n:#12304a;--b:#1f6feb;--l:#f4f7fb;--m:#64748b}*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;color:#1f2937;background:var(--l)}nav{background:var(--n);padding:16px max(20px,calc((100% - 1100px)/2));display:flex;gap:22px;flex-wrap:wrap}nav .brand{color:#fff;font-weight:700;margin-right:auto;text-decoration:none}nav a{color:#dbeafe;text-decoration:none}main{max-width:1100px;margin:auto;padding:52px 20px}h1{font-size:clamp(2rem,4vw,3.2rem);color:var(--n)}p{line-height:1.65}.lead{font-size:1.15rem;color:var(--m)}.hero,.card,.table-wrap{background:#fff;border-radius:14px;padding:32px;box-shadow:0 8px 24px #12304a14}.buttons{display:flex;gap:12px;flex-wrap:wrap;margin-top:26px}.button{display:inline-block;background:var(--b);color:#fff;padding:12px 18px;border-radius:8px;text-decoration:none;font-weight:700}.button.secondary{background:#e8eef7;color:var(--n)}.table-wrap{padding:0;overflow:auto}table{border-collapse:collapse;width:100%;min-width:650px}th,td{padding:16px 18px;text-align:left;border-bottom:1px solid #e5e7eb}th{background:#eaf2ff;color:var(--n)}.tag{background:#e8f7ee;color:#17653a;padding:5px 10px;border-radius:99px;font-size:.85rem}footer{text-align:center;padding:28px;color:var(--m);font-size:.9rem}</style></head><body><nav><a class="brand" href="<?= $esc($root('/')) ?>">Laravel POS Eloquent</a><a href="<?= $esc($root('/')) ?>">Home</a><a href="<?= $esc($root('/about')) ?>">About</a><a href="<?= $esc($root('/customers')) ?>">Customers</a><a href="<?= $esc($root('/users')) ?>">Users</a></nav><main>
<?php if ($path === '/about'): ?><section class="card"><h1>About This Application</h1><p>This TFA6 activity replaces TFA5 static arrays with a real Laravel data layer. Migrations define the tables, seeders insert sample records, Eloquent models retrieve records, and Blade views display them.</p></section>
<?php elseif ($path === '/customers'): ?><h1>Customer Accounts</h1><p class="lead">Records retrieved from the seeded customer data.</p><div class="table-wrap"><table><thead><tr><th>ID</th><th>Full Name</th><th>Email</th><th>Phone</th><th>Status</th></tr></thead><tbody><?php foreach ($store['customers'] as $c): ?><tr><td><?= $esc($c['id']) ?></td><td><?= $esc($c['full_name']) ?></td><td><?= $esc($c['email']) ?></td><td><?= $esc($c['phone']) ?></td><td><span class="tag">Active</span></td></tr><?php endforeach; ?></tbody></table></div>
<?php elseif ($path === '/users'): ?><h1>User Accounts</h1><p class="lead">Records retrieved from the seeded user data.</p><div class="table-wrap"><table><thead><tr><th>ID</th><th>Username</th><th>Full Name</th><th>Status</th></tr></thead><tbody><?php foreach ($store['users'] as $u): ?><tr><td><?= $esc($u['id']) ?></td><td><?= $esc($u['username']) ?></td><td><?= $esc($u['full_name']) ?></td><td><span class="tag">Active</span></td></tr><?php endforeach; ?></tbody></table></div>
<?php else: ?><section class="hero"><h1>From Arrays to Eloquent</h1><p class="lead">A database-backed Laravel POS application using migrations, seeders, Eloquent models, controllers, and Blade views.</p><div class="buttons"><a class="button" href="<?= $esc($root('/customers')) ?>">View Customers</a><a class="button secondary" href="<?= $esc($root('/users')) ?>">View Users</a></div></section><?php endif; ?></main><footer>IT0049 Web System Technologies &middot; TFA6</footer></body></html>
